// One-off: why does the close-range fire test miss?
import puppeteer from 'puppeteer-core';
import http from 'http';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PUBLIC_DIR = path.join(__dirname, '..', 'app', 'public');
const CHROME = '/usr/bin/google-chrome-stable';
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };

const srv = await new Promise(res => {
  const s = http.createServer((req, r) => {
    const f = path.join(PUBLIC_DIR, req.url === '/' ? '/index.html' : req.url.split('?')[0]);
    if (!fs.existsSync(f)) { r.writeHead(404); r.end(); return; }
    r.writeHead(200, { 'Content-Type': MIME[path.extname(f)] || 'text/plain' });
    fs.createReadStream(f).pipe(r);
  });
  s.listen(0, '127.0.0.1', () => res(s));
});

const browser = await puppeteer.launch({
  executablePath: CHROME, headless: 'new',
  args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'],
  defaultViewport: { width: 640, height: 360 },
});
const page = await browser.newPage();
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto(`http://127.0.0.1:${srv.address().port}/`, { waitUntil: 'networkidle0' });
await page.waitForFunction('window.GAME && window.GAME.ready');

const out = await page.evaluate(async () => {
  GAME.test.start();
  GAME.test.skipBuy();
  await new Promise(r => setTimeout(r, 300));
  const g = GAME.game;
  const log = [];
  g.events.onShot = info => log.push({
    hits: info.hits.map(h => ({ bot: h.bot ? h.bot.name : null, dmg: h.dmg, point: h.point.map(v => +v.toFixed(2)) })),
    hit: info.hit,
  });
  const b = GAME.test.botInfo()[0];
  GAME.test.pose(b.pos[0], 0, b.pos[2] + 4, 0, 0);
  GAME.test.aimAtBot(0);
  const p = g.player;
  const eye = g.eyePos();
  const basis = g.camBasis();
  GAME.game.player.fireCd = 0;
  GAME.test.fire();
  return {
    botPos: b.pos, botState: b.state,
    playerPos: [...p.pos], yaw: p.yaw, pitch: p.pitch,
    eye, fwd: basis.fwd,
    spread: g.spread,
    log,
    botAfter: GAME.test.botInfo()[0],
  };
});
console.log(JSON.stringify(out, null, 2));
await browser.close();
srv.close();
